package com.ips.ui;
import com.ips.dao.FeatureDAO;import com.ips.model.User;import javax.swing.*;import javax.swing.border.EmptyBorder;import java.awt.*;import java.sql.SQLException;import java.text.SimpleDateFormat;
public class HistoryFrame extends JFrame{
 public HistoryFrame(User user){UIStyle.configureFrame(this,"Attempt History",780,520);setDefaultCloseOperation(DISPOSE_ON_CLOSE);JPanel root=new JPanel(new BorderLayout(12,12));root.setBackground(UIStyle.BACKGROUND);root.setBorder(new EmptyBorder(24,26,24,26));root.add(UIStyle.heading("Attempt history"),BorderLayout.NORTH);try{var rows=new FeatureDAO().history(user.getId());Object[][] data=new Object[rows.size()][5];var fmt=new SimpleDateFormat("dd MMM yyyy, hh:mm a");for(int i=0;i<rows.size();i++){var r=rows.get(i);data[i]=new Object[]{r.id(),r.mode(),fmt.format(r.date()),r.score()+" / "+r.total(),r.total()==0?"0%":String.format("%.1f%%",100.0*r.score()/r.total())};}JTable t=new JTable(data,new String[]{"Attempt #","Mode","Date","Score","Accuracy"});AnalyticsFrame.styleTable(t);root.add(new JScrollPane(t),BorderLayout.CENTER);JLabel footer=new JLabel(rows.size()+" saved attempt(s)");footer.setForeground(UIStyle.MUTED);root.add(footer,BorderLayout.SOUTH);}catch(SQLException e){root.add(new JLabel("Could not load history: "+e.getMessage()),BorderLayout.CENTER);}setContentPane(root);}
}
